// end: generated by testdata/gen_quote_data.go

// corpus_strs decodes corpus_hex back into the byte sequences Go saw.
fn corpus_strs() []string {
	mut out := []string{len: corpus_hex.len}
	for i, h in corpus_hex {
		out[i] = unhex(h)
	}
	return out
}

// hx encodes s as hex, so a golden string can be written as data instead of a
// V literal that would have to spell its own backslashes.
fn hx(s string) string {
	mut out := []u8{}
	for c in s {
		out << hexdig(c >> 4)
		out << hexdig(c & 0xF)
	}
	return out.bytestr()
}

// from_hx is the inverse of hx.
fn from_hx(s string) string {
	return unhex(s)
}

fn hexdig(v u8) u8 {
	return if v < 10 { u8(48) + v } else { u8(87) + v }
}

// unhex decodes a hex string from the golden arrays back into raw bytes.
fn unhex(s string) string {
	mut out := []u8{}
	mut i := 0
	for i < s.len / 2 {
		mut b := u8(0)
		for j in 0 .. 2 {
			c := s[i * 2 + j]
			d := if c >= `0` && c <= `9` {
				c - `0`
			} else {
				c - `a` + 10
			}
			b = b << 4 | u8(d)
		}
		out << b
		i++
	}
	return out.bytestr()
}

struct Fnv {
mut:
	h u64
}

fn (mut f Fnv) b(v u8) {
	f.h ^= u64(v)
	f.h *= 0x100000001b3
}

// rune_str encodes r as UTF-8 the way Go's string(r) does, substituting
// U+FFFD for a surrogate, which Go cannot encode.
fn rune_str(r rune) string {
	if r < 0 || r > 0x10FFFF {
		return ''
	}
	mut rr := r
	if rr >= 0xD800 && rr <= 0xDFFF {
		rr = 0xFFFD
	}
	x := u32(rr)
	mut a := []u8{}
	if rr < 0x80 {
		a << u8(x)
	} else if rr < 0x800 {
		a << u8(0xC0 | x >> 6)
		a << u8(0x80 | x & 0x3F)
	} else if rr < 0x10000 {
		a << u8(0xE0 | x >> 12)
		a << u8(0x80 | (x >> 6) & 0x3F)
		a << u8(0x80 | x & 0x3F)
	} else {
		a << u8(0xF0 | x >> 18)
		a << u8(0x80 | (x >> 12) & 0x3F)
		a << u8(0x80 | (x >> 6) & 0x3F)
		a << u8(0x80 | x & 0x3F)
	}
	return a.bytestr()
}

fn test_quote_matches_go() {
	strs := corpus_strs()
	assert strs.len == gold_quote.len
	for i, s in strs {
		assert quote(s) == unhex(gold_quote[i]), 'quote mismatch at ' + i.str()
		assert quote_to_ascii(s) == unhex(gold_quote_to_ascii[i]), 'quote_to_ascii mismatch at ' + i.str()
		assert quote_to_graphic(s) == unhex(gold_quote_to_graphic[i]), 'quote_to_graphic mismatch at ' + i.str()
		// gold_append_quote was recorded with a "PRE" prefix already in place, so
		// the prefix is part of the expectation, not something to add again.
		mut buf := 'PRE'.bytes()
		append_quote(mut buf, s)
		assert buf.bytestr() == unhex(gold_append_quote[i]), 'append_quote mismatch at ' + i.str()
		assert can_backquote(s) == (gold_can_backquote[i] == 'true'), 'can_backquote mismatch at ' + i.str()
	}
}

fn test_append_quote_preserves_prefix() {
	// the append_* family must extend the caller's buffer, not replace it
	for i, s in corpus_strs() {
		mut got := 'PRE'.bytes()
		append_quote(mut got, s)
		assert got[..3].bytestr() == 'PRE', 'append_quote dropped the prefix at ' + i.str()
		assert got.len >= 5, 'append_quote produced no quoted output at ' + i.str()
		assert got.bytestr() == unhex(gold_append_quote[i]), 'append_quote mismatch at ' + i.str()
	}
}

fn test_append_quote_rune_preserves_prefix() {
	for i, rs in corpus_runes {
		mut got := 'PRE'.bytes()
		append_quote_rune(mut got, rune(rs.i64()))
		assert got[..3].bytestr() == 'PRE', 'append_quote_rune dropped the prefix at ' + i.str()
		assert got.bytestr() == unhex(gold_append_quote_rune[i]), 'append_quote_rune mismatch at ' + i.str()
	}
}

fn test_append_variants_extend_one_buffer() {
	// each append_* call extends dst in place, so a loop builds one buffer
	mut buf := []u8{}
	for _ in 0 .. 3 {
		append_quote(mut buf, 'a' + '\t' + 'b')
	}
	assert buf.bytestr() == from_hx('22615c746222').repeat(3) // "a\tb" three times
	mut all := 'x='.bytes()
	append_quote_to_ascii(mut all, 'caf' + '\u00e9')
	append_quote_to_graphic(mut all, 'a' + '\u00a0')
	append_quote_rune(mut all, 0x0A)
	append_quote_rune_to_ascii(mut all, 0x00E9)
	append_quote_rune_to_graphic(mut all, 0x3000)
	assert all.bytestr() == 'x=' + quote_to_ascii('caf' + '\u00e9') + quote_to_graphic('a' + '\u00a0') +
		quote_rune(0x0A) + quote_rune_to_ascii(0x00E9) + quote_rune_to_graphic(0x3000)
}

fn test_quote_rune_matches_go() {
	assert corpus_runes.len == gold_quote_rune.len
	for i, rs in corpus_runes {
		r := rune(rs.i64())
		assert quote_rune(r) == unhex(gold_quote_rune[i]), 'quote_rune mismatch at ' + i.str()
		assert quote_rune_to_ascii(r) == unhex(gold_quote_rune_to_ascii[i]), 'quote_rune_to_ascii mismatch at ' + i.str()
		assert quote_rune_to_graphic(r) == unhex(gold_quote_rune_to_graphic[i]), 'quote_rune_to_graphic mismatch at ' + i.str()
		assert is_print(r) == (gold_is_print[i] == 'true'), 'is_print mismatch at ' + i.str()
		assert is_graphic(r) == (gold_is_graphic[i] == 'true'), 'is_graphic mismatch at ' + i.str()
	}
}

fn test_is_print_exhaustive() {
	mut f := Fnv{
		h: 0xcbf29ce484222325
	}
	for r in 0 .. 0x10FFFF + 1 {
		f.b(if is_print(r) { u8(1) } else { u8(0) })
	}
	assert f.h == go_is_print_hash, 'is_print checksum mismatch'
}

fn test_is_graphic_exhaustive() {
	mut f := Fnv{
		h: 0xcbf29ce484222325
	}
	for r in 0 .. 0x10FFFF + 1 {
		f.b(if is_graphic(r) { u8(1) } else { u8(0) })
	}
	assert f.h == go_is_graphic_hash, 'is_graphic checksum mismatch'
}

fn test_can_backquote_exhaustive() {
	mut f := Fnv{
		h: 0xcbf29ce484222325
	}
	for r in 0 .. 0x10FFFF + 1 {
		f.b(if can_backquote(rune_str(r)) { u8(1) } else { u8(0) })
	}
	assert f.h == go_can_backquote_hash, 'can_backquote checksum mismatch'
}

// hx is used for the expected values below: a V literal cannot express a
// backslash escape that must stay two characters without the reader guessing.
// The hex below was produced by running Go, not written by hand: each one is
// Go's own output for the input named in the comment.
fn test_quote_basics() {
	assert quote('') == '""'
	assert quote('hello') == '"hello"'
	assert quote('a' + '\t' + 'b') == from_hx('22615c746222') // "a\tb"
	assert quote('a' + '"' + 'b') == from_hx('22615c226222') // "a\"b"
	assert quote('a' + '\\' + 'b') == from_hx('22615c5c6222') // "a\\b"
	assert quote('a' + '\x07' + 'b') == from_hx('22615c616222') // "a\ab"
	assert quote('a' + '\x0b' + 'b') == from_hx('22615c766222') // "a\vb"
	assert quote('a' + '\x7f' + 'b') == from_hx('22615c7837666222') // "a\x7fb"
	assert quote_rune(rune(0x61)) == "'a'"
	assert quote_rune(rune(0x0A)) == from_hx('275c6e27') // '\n'
	assert quote_rune(rune(0x27)) == from_hx('275c2727') // '\''
	// U+00E9 is printable, so quote keeps it; quote_to_ascii escapes it to
	// \u00e9 and quote_to_graphic keeps the letter.
	assert quote('caf' + '\u00e9') == from_hx('22636166c3a922') // "café"
	assert quote_to_ascii('caf' + '\u00e9') == from_hx('226361665c753030653922') // "caf\u00e9"
	assert quote_to_graphic('a' + '\u00e9') == from_hx('2261c3a922') // "aé"
}

fn test_is_print_basics() {
	assert is_print(rune(0x61)) // a
	assert is_print(rune(0x20)) // space
	assert !is_print(rune(0x0A)) // newline
	assert !is_print(0x7F)
	assert !is_print(-1)
	assert !is_print(0xD800) // a surrogate half
	assert is_print(0xFFFD)
	assert !is_print(0x110000)
}

// Expectations below were taken from Go 1.26.1's CanBackquote. A tab and a
// backslash are both allowed, since a raw string has no escapes. Every other
// control character is rejected, as are the backquote itself, DEL, invalid
// UTF-8 and the byte order mark U+FEFF.
fn test_can_backquote_basics() {
	assert can_backquote('')
	assert can_backquote('hello')
	assert can_backquote('has space')
	assert can_backquote('has' + '\t' + 'ab')
	assert !can_backquote('has' + '\n' + 'l')
	assert !can_backquote('has' + '\r' + 'l')
	assert !can_backquote('has' + '`')
	assert can_backquote('a' + '\\' + 'b')
	// a BOM may not appear in a raw string; the non-characters either side of
	// U+FFFF are accepted
	assert !can_backquote('\uFEFF')
	assert can_backquote('\uFFFE')
	assert can_backquote('\uFFFF')
	assert can_backquote('\u00e9' + '\u4e16')
}
